// ------------------------------------------------------------ configuration

interface Settings {
  apiBaseUrl: string;
  storeId: string;
  entryPath: string;
  routePaths: Record<string, string>;
  /** What the pages fetch themselves (their Data settings): "menu", "cities". */
  pageResources?: string[];
}

let settings: Settings = { apiBaseUrl: "", storeId: "", entryPath: "/", routePaths: {} };
export let storefront: Storefront;

/**
 * Called by router.tsx as each router is made: once in the browser, once per
 * request on the server. The storefront holds a visitor's cart and session,
 * so on the server it is only ever read empty, never acted on.
 */
export function configure(next: Settings, queries: QueryClient) {
  settings = next;
  storefront = new Storefront(next.apiBaseUrl, next.storeId, queries);
  // What the server refused in the cart: shown as any message is.
  storefront.onProblem = (message) => notice(message);
  // Pages that import the menu fetch it themselves: a chosen store loads only the store.
  storefront.loadsMenu = !next.pageResources?.includes("menu");
}

/**
 * A page's imports as bindings: one not fetched (no store chosen yet)
 * leaves the built-in of its name; an imported menu brings its store,
 * categories and the products shown online, as the storefront's own does.
 */
export function importedBindings(data: Json | undefined): Json {
  const out: Json = {};
  for (const [name, value] of Object.entries(data ?? {})) if (value != null) out[name] = value;
  const menu = out.menu;
  if (menu && typeof menu === "object" && Array.isArray(menu.categories)) {
    const categories = menu.categories as Json[];
    out.categories ??= categories;
    out.category ??= categories[0] ?? null;
    if (menu.store) out.store ??= menu.store;
    out.products ??= [
      ...categories.flatMap((category) => (Array.isArray(category?.products) ? category.products : [])),
      ...(Array.isArray(menu.uncategorised) ? menu.uncategorised : []),
    ].filter((product: Json) => product?.is_available_online !== false);
  }
  return out;
}

type AppRouter = { history: { push(path: string): void; replace(path: string): void }; invalidate(): Promise<void> };
let router: AppRouter | null = null;
export function useRouter(next: AppRouter) {
  router = next;
}

// ------------------------------------------------------------------ values

export function truthy(value: unknown): boolean {
  return value != null && value !== false && value !== "" && value !== 0;
}

export function text(value: unknown): string {
  if (value == null) return "";
  if (typeof value === "number") return Number.isInteger(value) ? String(value) : String(value);
  return String(value);
}

/** Anything that isn't a number counts as 0, as in the preview. */
export function num(value: unknown): number {
  return typeof value === "number" && Number.isFinite(value) ? value : 0;
}

const unsafeKeys = new Set(["__proto__", "constructor", "prototype"]);

export function read(value: unknown, path: unknown[]): any {
  let current: any = value;
  for (const key of path) {
    if (typeof key === "string" && unsafeKeys.has(key)) return null;
    if (Array.isArray(current)) {
      if (typeof key === "number" && Number.isInteger(key) && key >= 0 && key < current.length) current = current[key];
      else if (key === "length") current = current.length;
      else return null;
    } else if (typeof current === "string" && key === "length") {
      current = current.length;
    } else if (current && typeof current === "object" && Object.prototype.hasOwnProperty.call(current, key as string)) {
      current = current[key as string];
    } else {
      return null;
    }
  }
  return current === undefined ? null : current;
}

export function binary(op: string, left: unknown, right: () => unknown): unknown {
  if (op === "&&") return truthy(left) ? right() : left;
  if (op === "||") return truthy(left) ? left : right();
  if (op === "??") return left ?? right();
  const value = right();
  if (op === "==") return left === value || (left == null && value == null);
  if (op === "!=") return !(left === value || (left == null && value == null));
  if (typeof left === "string" && typeof value === "string") {
    if (op === "+") return left + value;
    if (op === "<") return left < value;
    if (op === ">") return left > value;
    if (op === "<=") return left <= value;
    if (op === ">=") return left >= value;
  }
  if (typeof left !== "number" || typeof value !== "number") return null;
  switch (op) {
    case "+": return left + value;
    case "-": return left - value;
    case "*": return left * value;
    case "/": return value === 0 ? null : left / value;
    case "%": return value === 0 ? null : left % value;
    case "<": return left < value;
    case ">": return left > value;
    case "<=": return left <= value;
    case ">=": return left >= value;
  }
  return null;
}

export interface Insets {
  $: "Insets";
  top: number;
  right: number;
  bottom: number;
  left: number;
}

export function insets(top: unknown, right: unknown, bottom: unknown, left: unknown): Insets {
  return { $: "Insets", top: num(top), right: num(right), bottom: num(bottom), left: num(left) };
}

/** A padding value as CSS: a number, Insets, or none. */
export function padding(value: unknown): string | undefined {
  if (typeof value === "number") return value + "px";
  if (value && typeof value === "object" && (value as Insets).$ === "Insets") {
    const v = value as Insets;
    return `${v.top}px ${v.right}px ${v.bottom}px ${v.left}px`;
  }
  return undefined;
}

export function border(width: unknown, color: unknown) {
  return { $: "Border", width: Math.max(0, num(width)), color: paint(color) ?? "var(--studio-border)" };
}

export function borderCss(value: unknown): string | undefined {
  if (!value || typeof value !== "object" || (value as Json).$ !== "Border") return undefined;
  const v = value as Json;
  return `${v.width}px solid ${v.color}`;
}

/** A colour: a theme variable (Color.primary) or a six-digit hex. */
export function paint(value: unknown): string | undefined {
  if (typeof value !== "string") return undefined;
  if (value.startsWith("var(--studio-") || /^#[0-9a-fA-F]{6}$/.test(value)) return value;
  return undefined;
}

export function gradient(style: string, stops: unknown[], begin: unknown, end: unknown): string {
  const colors = stops.map((stop) => paint(stop) ?? "transparent").join(", ");
  if (style === "radial") return `radial-gradient(circle, ${colors})`;
  if (style === "sweep") return `conic-gradient(${colors})`;
  // From begin towards end: CSS names the side it ends at.
  void begin;
  return `linear-gradient(${endDirection(typeof end === "string" ? end : "bottomCenter")}, ${colors})`;
}

function endDirection(anchor: string) {
  const map: Record<string, string> = {
    topLeft: "to top left", topCenter: "to top", top: "to top", topRight: "to top right",
    centerLeft: "to left", left: "to left", center: "to bottom", centerRight: "to right", right: "to right",
    bottomLeft: "to bottom left", bottomCenter: "to bottom", bottom: "to bottom", bottomRight: "to bottom right",
  };
  return map[anchor] ?? "to bottom";
}

const width = (bindings: Json) => num(read(bindings, ["viewport", "width"]));
export const isMobile = (bindings: Json) => width(bindings) < 768;
export const isTablet = (bindings: Json) => width(bindings) >= 768 && width(bindings) < 1024;
export const isDesktop = (bindings: Json) => width(bindings) >= 1024;

export function responsive(bindings: Json, base: unknown, md: unknown, lg: unknown) {
  const w = width(bindings);
  if (w >= 1024) return lg !== undefined ? lg : md !== undefined ? md : base;
  if (w >= 768) return md !== undefined ? md : base;
  return base;
}

/** A Route token's path: this project's own page, or the storefront's usual one. */
export function route(name: string): string {
  return (
    settings.routePaths[name] ??
    ({
      home: "/", menu: "/", cart: "/cart", checkout: "/checkout", orders: "/orders", account: "/account",
      addresses: "/addresses", resetPassword: "/reset-password", tracking: "/orders/$orderId",
      location: "/select-location", stores: "/select-store",
    } as Record<string, string>)[name] ??
    name
  );
}

/** A record's page (Route.product …): its page, the id's param, the usual path. */
const recordRoutes: Record<string, [string, string, string]> = {
  "Route.product": ["product", "productId", "/product/$productId"],
  "Route.category": ["category", "categoryId", "/category/$categoryId"],
  "Route.order": ["tracking", "orderId", "/orders/$orderId"],
};

function routePath(value: unknown): string {
  if (value && typeof value === "object" && typeof (value as Json).$ === "string") {
    const v = value as Json;
    const [page, param, usual] = recordRoutes[v.$] ?? recordRoutes["Route.order"];
    // The project's own page for it (/stores/$storeId/products/$productId …),
    // the record's id in its param; any other param is filled by navigate.
    const pattern = settings.routePaths[page] ?? usual;
    return pattern.split("/").map((part) => (part === "$" + param ? encodeURIComponent(text(v.id)) : part)).join("/");
  }
  return route(text(value));
}

// ------------------------------------------------------------- dark mode

/** The mode ToggleDarkMode switched to (data-theme on <html>); null: Config's. */
let themeOver: "light" | "dark" | null = null;

/** Whether the page is dark: switched to, or Config's (its color-scheme). */
export function isDarkMode(): boolean {
  if (themeOver) return themeOver === "dark";
  if (typeof document === "undefined") return false;
  return getComputedStyle(document.documentElement).colorScheme === "dark";
}

function toggleDarkMode() {
  themeOver = isDarkMode() ? "light" : "dark";
  document.documentElement.dataset.theme = themeOver;
}

export function fn(bindings: Json, name: string, args: unknown[]): unknown {
  const [a, b, c] = args;
  switch (name) {
    case "currentRoute": return read(bindings, ["route", "path"]) ?? "/";
    case "isDarkMode": return isDarkMode();
    case "isCurrentRoute": {
      const target = routePath(a);
      const pattern = target.split("/").map((part) => (part.startsWith("$") ? "[^/]+" : part.replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))).join("/");
      return new RegExp("^" + pattern + "$").test(text(read(bindings, ["route", "path"]) ?? "/"));
    }
    case "upper": return a == null ? null : text(a).toUpperCase();
    case "lower": return a == null ? null : text(a).toLowerCase();
    case "truncate": return a == null ? null : text(a).slice(0, Math.max(0, Math.trunc(num(b))));
    case "length":
    case "count": return typeof a === "string" || Array.isArray(a) ? a.length : 0;
    case "join": return Array.isArray(a) ? a.map((v) => (v && typeof v === "object" ? "" : text(v))).join(text(b)) : "";
    case "contains": return typeof a === "string" ? a.includes(text(b)) : Array.isArray(a) && a.includes(b);
    case "isEmpty": return a == null || a === "" || (Array.isArray(a) && a.length === 0);
    case "min": return Math.min(num(a), num(b));
    case "max": return Math.max(num(a), num(b));
    case "round": return Math.floor(num(a) + 0.5);
    case "floor": return Math.floor(num(a));
    case "ceil": return Math.ceil(num(a));
    case "clamp": return Math.min(Math.max(num(a), num(b)), num(c));
    case "take": return Array.isArray(a) ? a.slice(0, Math.max(0, Math.trunc(num(b)))) : [];
    case "first": return Array.isArray(a) && a.length ? a[0] : null;
    case "ratio": {
      const parts = text(a).split(":").map(Number);
      return parts.length === 2 && parts[0] > 0 && parts[1] > 0 ? parts[0] / parts[1] : 1;
    }
    case "discountPercent":
      return num(b) > num(a) && num(b) > 0 ? Math.min(100, Math.max(0, Math.floor((1 - num(a) / num(b)) * 100 + 0.5))) : 0;
    case "formatMoney": {
      // The page's store's currency, else the storefront's (the cart's
      // store's, a listed store's): never a currency none of them use.
      const currency = read(bindings, ["store", "currency"]) ?? storefront.currency;
      return `${currency} ${(num(a) / 100).toFixed(2)}`;
    }
    case "filter":
      return Array.isArray(a) ? a.filter((item) => read(item, text(b).split(".")) === c).slice(0, 200) : [];
    case "search": {
      if (!Array.isArray(a)) return [];
      const words = text(b).toLowerCase().trim().split(/\s+/).filter(Boolean);
      const fields = Array.isArray(c) ? c : [];
      return a
        .filter((item) => {
          const haystack = fields
            .map((field) => read(item, text(field).split(".")))
            .map((value) => (Array.isArray(value) ? value.join(" ") : text(value)))
            .join(" ")
            .toLowerCase();
          return words.every((word) => haystack.includes(word));
        })
        .slice(0, 200);
    }
  }
  return null;
}

/** ForEach: each item's element, or the empty one. */
export function each(list: unknown, limit: unknown, build: (item: any, index: number) => ReactNode, empty: ReactNode): ReactNode[] {
  const items = Array.isArray(list) ? list.slice(0, Math.min(100, Math.max(0, Math.trunc(num(limit))))) : [];
  if (items.length === 0) return empty == null ? [] : [empty];
  return items.map(build);
}

/** A ForEach item's key: its id where it has one, so a list that changes keeps its items. */
export function key(prefix: string, item: unknown, index: number): string {
  const id = item && typeof item === "object" ? (item as Json).id : undefined;
  return prefix + ":" + (id != null ? "id:" + text(id) : "at:" + index);
}

export function scrollTo(id: string) {
  document.getElementById("studio-" + id)?.scrollIntoView({ behavior: "smooth", block: "start" });
}

/** Elements keyed by position where they have no key of their own. */
export function kids(children: unknown): ReactNode[] {
  if (!Array.isArray(children)) return children == null ? [] : [children as ReactNode];
  return children.map((child, index) =>
    child && typeof child === "object" && "key" in (child as ReactElement) && (child as ReactElement).key != null ? (
      child
    ) : (
      <Fragment key={"at:" + index}>{child as ReactNode}</Fragment>
    ),
  );
}

// ---------------------------------------------------------------- notices

type Notice = { id: number; message: string };
let notices: Notice[] = [];
const noticeListeners = new Set<() => void>();
let noticeId = 0;

export function notice(message: string) {
  const id = ++noticeId;
  notices = [{ id, message }];
  noticeListeners.forEach((listener) => listener());
  // How long it shows: Config's notice (theme.css's --studio-notice-ms), else 3.5s.
  const ms = typeof document === "undefined" ? 0 : Number(getComputedStyle(document.documentElement).getPropertyValue("--studio-notice-ms"));
  setTimeout(() => {
    notices = notices.filter((item) => item.id !== id);
    noticeListeners.forEach((listener) => listener());
  }, ms > 0 ? ms : 3500);
}

const noServerNotices: Notice[] = [];

function Notices() {
  const shown = useSyncExternalStore(
    (listener) => {
      noticeListeners.add(listener);
      return () => noticeListeners.delete(listener);
    },
    () => notices,
    () => noServerNotices,
  );
  return (
    <div className="studio-notices" role="status" aria-live="polite">
      {shown.map((item) => (
        <div key={item.id} className="studio-notice">
          {item.message}
        </div>
      ))}
    </div>
  );
}

